def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)  # end of input symbol

def expression() -> int:
  # expression(v) → ws term(v) { '+' ws term(w) « v := v + w » }
  ws()
  v = term()
  while sym == '+':
    nxt()
    ws()
    w = term()
    v = v + w
  return v

